template <class Call>
bool Run(const core::QueryArguments &a, std::vector<core::AuxRow> &out, Call call) {
  int64_t p1 = 0;
  if (!kit::ArgI64(a, 0, 0, p1))
    return false;
  std::string p2;
  if (!kit::ArgText(a, 1, p2))
    return false;
  secq24vgen_result *r = call(p1, reinterpret_cast<const uint8_t *>(p2.data()), p2.size());
  if (!r)
    return false;
  const size_t n = secq24vgen_result_len(r);
  out.reserve(out.size() + n);
  for (size_t i = 0; i < n; ++i) {
    core::AuxRow row;
    {
      const uint8_t *b0 = nullptr;
      size_t l0 = 0;
      row.values.push_back(secq24vgen_result_c0(r, i, &b0, &l0) ? kit::OutText(b0, l0) : kit::OutNull(core::AuxType::String));
    }
    {
      const uint8_t *b1 = nullptr;
      size_t l1 = 0;
      row.values.push_back(secq24vgen_result_c1(r, i, &b1, &l1) ? kit::OutText(b1, l1) : kit::OutNull(core::AuxType::String));
    }
    {
      int64_t v2 = 0;
      row.values.push_back(secq24vgen_result_c2(r, i, &v2) ? kit::OutI64(v2) : kit::OutNull(core::AuxType::Int64));
    }
    {
      uint64_t v3 = 0;
      row.values.push_back(secq24vgen_result_c3(r, i, &v3) ? kit::OutF64(v3) : kit::OutNull(core::AuxType::Double));
    }
    out.push_back(std::move(row));
  }
  secq24vgen_result_free(r);
  return true;
}

bool Execute(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq24vgen_execute(static_cast<const secq24vgen_state *>(s), x...); });
}

bool Answer(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq24vgens_answer(static_cast<const secq24vgens_reading *>(s), x...); });
}

